/* DORMIED Universal Search — client-side module v20260529 */
(function(){'use strict';
var idx=null,promise=null,CAP=5,DEBOUNCE=150;
/* Recently opened results, newest first. Stores URLs ONLY and resolves them
   against search-index.json at render time, so an entry whose page has been
   deleted disappears by itself instead of becoming a dead row -- three URLs
   were removed from this site in a single day while this was being written.
   It also means a stored row can never show a stale title or headshot.
   localStorage throws on ACCESS in private browsing, not just on write, which
   is why both helpers are wrapped (same reason as readStore in js/ticker.js).
   This is per-browser and never leaves the device. */
var KEY_RECENT='dormied.recent',RECENT_CAP=5;
function readStore(k){try{return window.localStorage.getItem(k);}catch(e){return null;}}
function writeStore(k,v){try{window.localStorage.setItem(k,v);}catch(e){}}
function recentGet(){
  var raw=readStore(KEY_RECENT);
  if(!raw)return [];
  try{
    var a=JSON.parse(raw);
    if(!Array.isArray(a))return [];
    return a.filter(function(u){return typeof u==='string'&&u.charAt(0)==='/';}).slice(0,RECENT_CAP);
  }catch(e){return [];}
}
function recentAdd(url){
  if(!url||url.charAt(0)!=='/')return;
  var a=recentGet().filter(function(u){return u!==url;});
  a.unshift(url);
  writeStore(KEY_RECENT,JSON.stringify(a.slice(0,RECENT_CAP)));
}
function recentClear(){writeStore(KEY_RECENT,'[]');}
function load(){
  if(idx)return Promise.resolve(idx);
  if(promise)return promise;
  promise=fetch('/search-index.json').then(function(r){return r.json();}).then(function(d){idx=d.entries;return idx;}).catch(function(){idx=[];return idx;});
  return promise;
}
function esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function filter(q){
  if(!q||q.length<2)return null;
  var lq=q.toLowerCase().trim();
  var all=idx.filter(function(e){return e.search_text.indexOf(lq)>=0||e.title.toLowerCase().indexOf(lq)>=0;});
  all.sort(function(a,b){
    var at=a.title.toLowerCase(),bt=b.title.toLowerCase();
    var as=at.indexOf(lq)===0?0:(at.indexOf(lq)>=0?1:2);
    var bs=bt.indexOf(lq)===0?0:(bt.indexOf(lq)>=0?1:2);
    if(as!==bs)return as-bs;
    return at<bt?-1:at>bt?1:0;
  });
  var g={brand:[],'witb-player':[],news:[],scorecard:[]};
  for(var i=0;i<all.length;i++){var e=all[i];if(g[e.type]&&g[e.type].length<CAP)g[e.type].push(e);}
  return g;
}
/* Static thumbnails (see scripts/lib/thumbs.js). /_vercel/image bills per
   transformation and returns 402 once the free tier runs out, which is how
   every headshot in this dropdown went missing. The path rule MUST match
   scripts/lib/thumbs.js exactly; an unmapped source falls through to the
   original URL and then to the img onerror. */
function vitUrl(src,w){
  if(!src)return src;
  var m=String(src).match(/\/storage\/v1\/object\/public\/dormied-articles\/([^/?]+)\/([^/?]+)/)
       ||String(src).match(/^\/images\/(logos|articles|players|scorecard)\/([^/?]+)/);
  if(!m)return src;
  var ver=String(src).match(/[?&]v=(\d{1,4})\b/);
  var base=m[2].replace(/\.[a-z0-9]+$/i,'')+(ver?'-v'+ver[1]:'');
  if(!/^[A-Za-z0-9._-]+$/.test(base))return src;
  return '/images/thumbs/'+m[1]+'/'+base+'-'+w+'.webp';
}
function renderWitbRow(e){
  /* Headshot when we have one (thumbnail is set by generate-search-index.js from
     the witb_players table), else the club icon. object-position is above centre:
     these are head-and-shoulders crops and a centred square cuts the head. */
  var face=e.thumbnail
    ? '<img src="'+esc(vitUrl(e.thumbnail,80))+'" alt="" width="28" height="28" loading="lazy" decoding="async" style="width:28px;height:28px;min-width:28px;border-radius:3px;object-fit:cover;object-position:50% 12%;background:var(--bg-raised);flex-shrink:0;display:block" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'inline-flex\'">'
      +'<span style="display:none;width:28px;height:28px;min-width:28px;align-items:center;justify-content:center;background:var(--bg-raised);border-radius:3px;flex-shrink:0"><img src="/images/icons/witb-golfer.svg" alt="" width="20" height="20" style="object-fit:contain;display:block"></span>'
    : '<span style="width:28px;height:28px;min-width:28px;display:inline-flex;align-items:center;justify-content:center;background:var(--bg-raised);border-radius:3px;flex-shrink:0"><img src="/images/icons/witb-golfer.svg" alt="" width="20" height="20" style="object-fit:contain;display:block"></span>';
  return '<a href="'+esc(e.url)+'" class="search-result" role="option">'+
    face+
    '<div class="search-result-body">'+
      '<div class="search-result-title">'+esc(e.title)+'</div>'+
      (e.subtitle?'<div class="search-result-subtitle">'+esc(e.subtitle)+'</div>':'')+
    '</div>'+
  '</a>';
}
/* Dispatches on the entry's own type rather than a section-wide one, so a
   mixed list (Recent) renders each row the way its own section would. */
function renderRow(e){
  if(e.type==='witb-player')return renderWitbRow(e);
  return '<a href="'+esc(e.url)+'" class="search-result" role="option">'+
    '<img class="search-result-thumb" src="'+esc(e.thumbnail?vitUrl(e.thumbnail,80):'/images/dormied-icon.png')+'" alt="" width="32" height="32" loading="lazy" onerror="this.style.visibility=\'hidden\'">'+
    '<div class="search-result-body">'+
      '<div class="search-result-title">'+esc(e.title)+'</div>'+
      (e.subtitle?'<div class="search-result-subtitle">'+esc(e.subtitle)+'</div>':'')+
    '</div>'+
  '</a>';
}
function renderSection(label,items){
  return '<div class="search-section"><div class="search-section-label">'+esc(label)+'</div>'+items.map(renderRow).join('')+'</div>';
}
/* Resolve stored URLs against the loaded index, dropping any whose page is
   gone. Returns '' when nothing survives, which is also the first-visit state. */
function renderRecent(el,emptyEl){
  var urls=recentGet();
  if(!urls.length||!idx){el.innerHTML='';emptyEl.hidden=true;return;}
  var byUrl={};
  for(var i=0;i<idx.length;i++)byUrl[idx[i].url]=idx[i];
  var items=[];
  for(var j=0;j<urls.length;j++)if(byUrl[urls[j]])items.push(byUrl[urls[j]]);
  if(!items.length){el.innerHTML='';emptyEl.hidden=true;return;}
  /* The header is presentational: role=listbox wants options as children, and
     a label and a button are neither. */
  el.innerHTML='<div class="search-section"><div class="search-section-head" role="presentation">'+
      '<span class="search-section-label">Recent</span>'+
      '<button type="button" class="search-recent-clear" aria-label="Clear recent searches">Clear</button>'+
    '</div>'+items.map(renderRow).join('')+'</div>';
  emptyEl.hidden=true;
}
function render(g,el,emptyEl){
  if(!g){el.innerHTML='';emptyEl.hidden=true;return;}
  var total=g.brand.length+g['witb-player'].length+g.news.length+g.scorecard.length;
  if(total===0){el.innerHTML='';emptyEl.hidden=false;return;}
  var html='';
  if(g.brand.length)html+=renderSection('Brands',g.brand);
  if(g['witb-player'].length)html+=renderSection('WITB',g['witb-player']);
  if(g.news.length)html+=renderSection('News',g.news);
  if(g.scorecard.length)html+=renderSection('Scorecard',g.scorecard);
  el.innerHTML=html;
  emptyEl.hidden=true;
}
function debounce(fn,ms){var t;return function(){clearTimeout(t);var a=arguments,c=this;t=setTimeout(function(){fn.apply(c,a);},ms);};}
function init(){
  var trigger=document.querySelector('.site-search-trigger');
  var panel=document.querySelector('.site-search-panel');
  var input=document.querySelector('.site-search-input');
  var closeBtn=document.querySelector('.site-search-close');
  var resultsEl=document.querySelector('.site-search-results');
  var emptyEl=document.querySelector('.site-search-empty');
  if(!trigger||!panel||!input)return;
  /* Below the 2-character threshold the panel shows Recent instead of nothing,
     which covers both opening the panel and deleting back to an empty box. */
  function showRecent(){load().then(function(){renderRecent(resultsEl,emptyEl);});}
  function openPanel(){panel.hidden=false;trigger.setAttribute('aria-expanded','true');input.focus();showRecent();}
  function closePanel(){panel.hidden=true;trigger.setAttribute('aria-expanded','false');input.value='';resultsEl.innerHTML='';emptyEl.hidden=true;}
  trigger.addEventListener('click',openPanel);
  if(closeBtn)closeBtn.addEventListener('click',closePanel);
  input.addEventListener('input',debounce(function(){
    var q=input.value.trim();
    if(q.length<2){showRecent();return;}
    load().then(function(){render(filter(q),resultsEl,emptyEl);});
  },DEBOUNCE));
  /* Record on activation, not on input: the handler above is debounced and
     fires per keystroke, so recording there would store "k", "ko", "kor".
     localStorage writes are synchronous, so this completes before the link
     navigates. Delegated, because the rows are replaced on every render. */
  resultsEl.addEventListener('click',function(e){
    var clear=e.target.closest&&e.target.closest('.search-recent-clear');
    if(clear){e.preventDefault();recentClear();renderRecent(resultsEl,emptyEl);input.focus();return;}
    var row=e.target.closest&&e.target.closest('a.search-result');
    if(row)recentAdd(row.getAttribute('href'));
  });
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!panel.hidden)closePanel();});
  document.addEventListener('click',function(e){if(panel.hidden)return;if(panel.contains(e.target)||trigger.contains(e.target))return;closePanel();});
}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}
})();
